def _split_pair(part):
    k, _, v = part.partition('=')
    return k.strip(), v.strip()


def _non_empty(parts):
    return [p for p in parts if p.strip()]


def _build(pairs):
    out = {}
    for k, v in pairs:
        out[k] = v
    return out


def parse(s):
    return _build([_split_pair(p) for p in _non_empty(s.split(';'))])

