def fetch_json(url, retries=3, timeout=5):
    last_error = None
    for _ in range(retries + 1):
        try:
            resp = requests.get(url, timeout=timeout)
            resp.raise_for_status()
            return resp.json()
        except requests.RequestException as exc:
            last_error = exc
    raise FetchError(url) from last_error

